    public init(inset: Bool = false, x: CGFloat, y: CGFloat, blur: CGFloat, spread: CGFloat = 0,
                rgb: (Double, Double, Double), alpha: Double) {
        self.inset = inset
        self.x = x; self.y = y; self.blur = blur; self.spread = spread
        self.rgb = SIMD3(rgb.0, rgb.1, rgb.2)
